WITH params AS (SELECT coalesce(%s::text, '') AS ma_vt, coalesce(%s::text, '') AS ma_loai_vt, coalesce(%s::text, '') AS ma_dvcs, coalesce(%s::text, '') AS status, %s::integer AS authenticated_user_id, %s::integer AS row_limit), scope AS (SELECT p.*, u.user_id AS authorized_user_id, coalesce(u.ds_branchs, '') AS ds_branchs, coalesce(u.is_super, 0) = 1 OR coalesce(u.ds_branchs, '') = '' AS unrestricted FROM params p LEFT JOIN public.userinfo u ON u.user_id = p.authenticated_user_id)
SELECT v.ma_vt, v.ma_vt2, v.ten_vt, v.ten_vt2, v.part_no, v.model, v.dvt, v.ma_loai_vt, v.nh_vt1, v.nh_vt2, v.nh_vt3, v.nh_vt4, v.nh_vt5, v.nh_vt6, v.nh_vt7, v.ds_ma_dvcs, v.vt_ton_kho, v.lo_yn, v.seri_yn, v.tk_vt, v.tk_gv, v.tk_dt, v.ma_cd_gt, v.ma_cp, v.ma_vv, v.moq, v.leadtime, v.leadtime_sx, v.status, v.date0, v.time0, v.user_id0, v.date2, v.time2, v.user_id2, count(*) OVER () AS total FROM public.dmvt v CROSS JOIN scope s WHERE s.authorized_user_id IS NOT NULL AND (s.ma_vt = '' OR v.ma_vt = ANY(string_to_array(s.ma_vt, ','))) AND (s.ma_loai_vt = '' OR v.ma_loai_vt = ANY(string_to_array(s.ma_loai_vt, ','))) AND (s.ma_dvcs = '' OR v.ds_ma_dvcs = '' OR string_to_array(v.ds_ma_dvcs, ',') && string_to_array(s.ma_dvcs, ',')) AND (s.status = '' OR v.status::text = ANY(string_to_array(s.status, ','))) AND (s.unrestricted OR v.ds_ma_dvcs = '' OR EXISTS (SELECT 1 FROM unnest(string_to_array(v.ds_ma_dvcs, ',')) x WHERE x = ANY(string_to_array(s.ds_branchs, ',')))) ORDER BY v.ma_vt LIMIT (SELECT row_limit FROM params);
